<section class="dash-card" id="skills"><div class="card-title"><h2>مهارت‌های من</h2><span><?=count($skills)?> مهارت</span></div><div class="skill-list"><?php foreach($skills as $skill):?><span class="skill-tag"><?=e($skill['name'])?><small><?=e($skill['level'])?></small></span><?php endforeach;?><?php if(!$skills):?><p class="muted">هنوز مهارتی اضافه نکرده‌اید.</p><?php endif;?></div><form class="skill-form" method="post" action="<?=url('/dashboard/freelancer/skills')?>"><?=csrf_field()?><select name="skill_id" required><option value="">انتخاب مهارت</option><?php foreach($availableSkills as $skill):?><option value="<?=e($skill['id'])?>"><?=e($skill['name'])?></option><?php endforeach;?></select><select name="level"><option value="beginner">مقدماتی</option><option value="intermediate">متوسط</option><option value="advanced">پیشرفته</option><option value="expert">متخصص</option></select><button class="button" type="submit">افزودن</button></form></section>